using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;

public static class NativePresetTests {
 static int passed;
 static string root,app;
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);passed++;}
 static void Wave(string path,bool silent){using(var writer=new BinaryWriter(File.Create(path))){int samples=48000;writer.Write(Encoding.ASCII.GetBytes("RIFF"));writer.Write(36+samples*2);writer.Write(Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(24000);writer.Write(48000);writer.Write((short)2);writer.Write((short)16);writer.Write(Encoding.ASCII.GetBytes("data"));writer.Write(samples*2);for(int i=0;i<samples;i++)writer.Write((short)(silent?0:Math.Sin(i*0.05)*6000));}}
 static async Task<bool> Reject(Func<Task> action){try{await action();return false;}catch(ArgumentException){return true;}catch(IOException){return true;}}
 static void Package(string file,object manifest,Dictionary<string,string> extra){using(var zip=ZipFile.Open(file,ZipArchiveMode.Create)){using(var writer=new StreamWriter(zip.CreateEntry("preset.json").Open()))writer.Write(Json.Serialize(manifest));foreach(var pair in extra)using(var writer=new StreamWriter(zip.CreateEntry(pair.Key).Open()))writer.Write(pair.Value);}}
 public static int Main(string[] args){root=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","..","work","preset-tests-"+Guid.NewGuid().ToString("N")));app=AppDomain.CurrentDomain.BaseDirectory;Directory.CreateDirectory(root);bool ok=false;try{Run(args).GetAwaiter().GetResult();ok=true;Console.WriteLine("PASS "+passed+" native preset checks");return 0;}catch(Exception e){Console.Error.WriteLine(e);Console.Error.WriteLine("Fixtures retained: "+root);return 1;}finally{string work=Path.GetFullPath(Path.Combine(app,"..","..","work"));if(ok&&root.StartsWith(work+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(root).StartsWith("preset-tests-",StringComparison.Ordinal))Directory.Delete(root,true);}}
 static async Task Run(string[] args){
  string text=Path.Combine(root,"captain.txt");File.WriteAllText(text,"A witty captain, clear and friendly.");string character=await PersonalPresets.Import(root,"character",new[]{text},"",CancellationToken.None,delegate{});
  Check(PersonalPresets.Description(root,character).Contains("witty captain"),"native character import retains description");PersonalPresets.Update(root,character,"character","Renamed captain","Updated character",null);Check(PersonalPresets.Description(root,character)=="Updated character","native character edit updates description");
  string export=Path.Combine(root,"character.kavychka");PersonalPresets.Export(root,character,"character",export);PersonalPresets.Export(root,character,"character",export);using(var zip=ZipFile.OpenRead(export))Check(zip.Entries.Count==1&&zip.Entries[0].FullName=="preset.json","character exports atomically without other preferences");
  string dirty=Path.Combine(root,"dirty.kavychka");Package(dirty,new{version=1,kind="character",name="Clean",description="Clean description",api_key="do not import",work_days=new[]{6}},new Dictionary<string,string>{{"credentials.json","do not extract"}});string imported=await PersonalPresets.Import(root,"character",new[]{dirty},"",CancellationToken.None,delegate{});string folder=Path.Combine(root,"presets",imported);Check(Directory.GetFiles(folder).Length==1&&!File.ReadAllText(Path.Combine(folder,"preset.json")).Contains("api_key"),"native package import strips unrelated files and metadata");
  foreach(string bad in new[]{"../outside.wav","C:/outside.wav","nested/../../outside.png"}){string file=Path.Combine(root,Guid.NewGuid()+".kavychka");Package(file,new{version=1,kind="visual",name="Bad",file=bad},new Dictionary<string,string>());Check(await Reject(async delegate{await PersonalPresets.Import(root,"visual",new[]{file},"",CancellationToken.None,delegate{});}),"native import rejects escaping reference "+bad);}
  string program=Path.Combine(root,"program.kavychka");Package(program,new{version=1,kind="character",name="Bad",description="Description"},new Dictionary<string,string>{{"run.exe","program"}});Check(await Reject(async delegate{await PersonalPresets.Import(root,"character",new[]{program},"",CancellationToken.None,delegate{});}),"native import rejects executable archive entries");
  string png=Path.Combine(root,"portrait.png");using(var bitmap=new Bitmap(64,64)){using(var g=Graphics.FromImage(bitmap))g.Clear(Color.CornflowerBlue);bitmap.Save(png);}string visual=await PersonalPresets.Import(root,"visual",new[]{png},"",CancellationToken.None,delegate{});using(var image=Image.FromFile(PersonalPresets.FilePath(root,visual,"visual")))Check(image.Width==64&&image.Height==64,"native visual import decodes a real image");
  var before=PersonalPresets.List(root).Count;using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();bool stopped=false;try{await PersonalPresets.Import(root,"character",new[]{text},"",cancelled.Token,delegate{});}catch(OperationCanceledException){stopped=true;}Check(stopped&&PersonalPresets.List(root).Count==before,"cancelled import adds no preset");}
  bool invalid=false;try{PersonalPresets.SaveCharacter(root,"","Invalid",new string('x',4001));}catch(ArgumentException){invalid=true;}Check(invalid&&PersonalPresets.List(root).Count==before,"invalid character edit leaves preset inventory unchanged");
  if(args.Length<1)throw new ArgumentException("Pass a verified ffmpeg executable to test native audio conversion");string media=Path.Combine(root,"media");Directory.CreateDirectory(media);File.Copy(args[0],Path.Combine(media,"ffmpeg.exe"));string wav=Path.Combine(root,"source.wav"),mp3=Path.Combine(root,"source recording.mp3");Wave(wav,false);MediaTools.Run(args[0],"-i "+MediaTools.Q(wav)+" "+MediaTools.Q(mp3),CancellationToken.None);
  string voice=await PersonalPresets.Import(root,"voice",new[]{mp3,wav},"",CancellationToken.None,delegate{});Check(PersonalPresets.Transcripts(root,voice).Length==2,"native voice import accepts multiple recordings and MP3");
  string preview=await PersonalPresets.PreviewAudio(root,voice,0,CancellationToken.None,delegate{});Check(Math.Abs(MediaTools.WaveSeconds(preview)-2)<0.1,"native audio is converted to a playable 24 kHz WAV preview");PersonalPresets.Update(root,voice,"voice","My voice","",new[]{"First exact transcript","Second exact transcript"});Check(PersonalPresets.Transcripts(root,voice)[1]=="Second exact transcript","voice transcripts survive native edit");
  string voiceExport=Path.Combine(root,"voice.kavychka");PersonalPresets.Export(root,voice,"voice",voiceExport);using(var zip=ZipFile.OpenRead(voiceExport))Check(zip.Entries.Count==3&&zip.Entries.All(e=>!e.Name.Contains("preview")),"voice export contains only references and metadata");string voiceCopy=await PersonalPresets.Import(root,"voice",new[]{voiceExport},"",CancellationToken.None,delegate{});Check(PersonalPresets.Transcripts(root,voiceCopy).SequenceEqual(new[]{"First exact transcript","Second exact transcript"}),"native voice package round trip retains all transcripts");
  Wave(wav,true);int count=PersonalPresets.List(root).Count;Check(await Reject(async delegate{await PersonalPresets.Import(root,"voice",new[]{wav},"",CancellationToken.None,delegate{});})&&PersonalPresets.List(root).Count==count,"silent audio is rejected without a partial preset");
  PersonalPresets.Delete(root,voice,"voice");Check(File.Exists(mp3)&&File.Exists(voiceExport)&&PersonalPresets.List(root).Any(p=>Convert.ToString(p["id"])==voiceCopy),"deleting a preset preserves source files, export and other presets");
  string defaultVoice=PersonalPresets.CloneDefaultVoice(root,app,"Default copy","Exact transcript");Check(PersonalPresets.Transcripts(root,defaultVoice)[0]=="Exact transcript","default voice can be saved as an independent user preset");
 }
}
